def cell_to_region(cell_num, is_row=True):
    if is_row:
        grids = [[0, 3], [5, 8], [10, 13], [15, 18], [20, 23], [25, 27]]
    else:
        grids = [[0, 3], [5, 8], [10, 13], [15, 18], [20, 23], [25, 27]]
    return grids[cell_num]

for r in range(6):
    for c in range(6):
        val = output_cells_6x6[r][c]
        if val != 0:
            row_cells, col_cells = cell_to_region(r, True), cell_to_region(c, False)
            for rr in range(row_cells[0], row_cells[1]+1):
                for cc in range(col_cells[0], col_cells[1]+1):
                    output_grid[rr][cc] = val

# Verify
print(f"Grid: {len(output_grid)}×{len(output_grid[0])}")
print(f"2s: {sum(row.count(2) for row in output_grid)}, 3s: {sum(row.count(3) for row in output_grid)}")

