test_input_measures = [
    (1, 12, 3),   # Row 1, col 12 is 3
    (6, 2, 2),    # Row 6, col 2 is 2
    (6, 22, 2),   # Row 6, col 22 is 2
    (16, 2, 2),   # Row 16, col 2 is 2
    (21, 12, 3),  # Row 21, col 12 is 3
]

def get_cell(pos):
    regions = [(0,3), (5,8), (10,13), (15,18), (20,23), (25,27)]
    for (r_start, r_end) in regions:
        if r_start <= pos <= r_end:
            return regions.index((r_start, r_end))
    return 0

print("Input cell mapping:")
input_cells = {}
for (r, c_edge, val) in test_input_measures:
    r_cell = get_cell(r)
    c_cell = get_cell(c_edge)
    print(f"  Grid ({r},{c_edge})={val} → Cell ({r_cell},{c_cell})")
    input_cells[(r_cell, c_cell)] = val

